-- Prediction Query
SELECT league.name FROM league INNER JOIN (SELECT league_id, SUM(home_team_goal) AS total_home_goals, COUNT(*) AS home_team_count FROM match WHERE season = '2009/2010' GROUP BY league_id) AS homegoals ON league.id = homegoals.league_id INNER JOIN (SELECT league_id, SUM(away_team_goal) AS total_away_goals, COUNT(*) AS away_team_count FROM match WHERE season = '2009/2010' GROUP BY league_id) AS awaygoals ON league.id = awaygoals.league_id WHERE homegoals.total_home_goals * awaygoals.away_team_count > awaygoals.total_away_goals * homegoals.home_team_count;

